alter table public.customer_reward_issuances drop constraint if exists customer_reward_issuances_source_type_check;
alter table public.customer_reward_issuances add constraint customer_reward_issuances_source_type_check check (source_type in ('birthday','milestone','vip','challenge'));
alter table public.customer_reward_issuances drop constraint if exists customer_reward_issuances_reward_type_check;
alter table public.customer_reward_issuances add constraint customer_reward_issuances_reward_type_check check (reward_type in ('voucher','percentage_discount','fixed_discount','free_item','free_delivery','loyalty_points','wallet_credit','bonus_stamps','vip_bonus','referral_bonus'));
alter table public.customer_reward_fraud_flags drop constraint if exists customer_reward_fraud_flags_source_type_check;
alter table public.customer_reward_fraud_flags add constraint customer_reward_fraud_flags_source_type_check check (source_type in ('birthday','milestone','vip','challenge','manual'));
alter table public.customer_credit_ledger drop constraint if exists customer_credit_ledger_entry_type_check;
alter table public.customer_credit_ledger add constraint customer_credit_ledger_entry_type_check check (entry_type in ('gift_card','refund_credit','manual_credit','order_redemption','referral_credit','birthday_credit','milestone_credit','vip_credit','challenge_credit'));
alter table public.customer_loyalty_ledger drop constraint if exists customer_loyalty_ledger_entry_type_check;
alter table public.customer_loyalty_ledger add constraint customer_loyalty_ledger_entry_type_check check (entry_type in ('order_earned','reward_redeemed','manual_adjustment','refund_reversal','birthday_bonus','referral_bonus','milestone_bonus','vip_bonus','challenge_bonus'));

create or replace function private.challenge_audience_matches(c public.restaurant_challenges, uid uuid)
returns boolean language plpgsql stable security definer set search_path='' as $$
declare order_count bigint; tier_id uuid; target_tier uuid; dob date; referral_count bigint;
begin
  if c.target_audience='all' then return true; end if;
  if c.target_audience='vip' then return exists(select 1 from public.customer_vip_memberships m where m.restaurant_id=c.restaurant_id and m.customer_user_id=uid and m.current_tier_id is not null); end if;
  if c.target_audience='tier' then target_tier:=nullif(c.target_config->>'tier_id','')::uuid; select current_tier_id into tier_id from public.customer_vip_memberships where restaurant_id=c.restaurant_id and customer_user_id=uid; return target_tier is not null and tier_id=target_tier; end if;
  select count(*) into order_count from public.orders where restaurant_id=c.restaurant_id and customer_user_id=uid and payment_status='paid' and order_status='completed';
  if c.target_audience='new' then return order_count<=1; end if;
  if c.target_audience='returning' then return order_count>1; end if;
  if c.target_audience='birthday' then select date_of_birth into dob from public.customer_profiles where user_id=uid; return dob is not null and extract(month from dob)=extract(month from now()) and extract(day from dob)=extract(day from now()); end if;
  if c.target_audience='referral' then select count(*) into referral_count from public.customer_referrals where restaurant_id=c.restaurant_id and referrer_user_id=uid and status='qualified'; return referral_count>0; end if;
  if c.target_audience='custom' then return exists(select 1 from public.customer_challenge_custom_metrics m where m.restaurant_id=c.restaurant_id and m.customer_user_id=uid and m.metric_key=coalesce(c.target_config->>'metric_key','') and m.metric_value>=coalesce((c.target_config->>'minimum_value')::bigint,1)); end if;
  return false;
end $$;

create or replace function private.challenge_metric_value(cond public.restaurant_challenge_conditions,c public.restaurant_challenges,uid uuid,trigger_order_id uuid)
returns bigint language plpgsql stable security definer set search_path='' as $$
declare v bigint:=0; start_time timestamptz:=c.starts_at; finish_time timestamptz:=coalesce(c.ends_at,'infinity'::timestamptz); key text;
begin
  if cond.condition_type='order_count' then select count(*) into v from public.orders where restaurant_id=c.restaurant_id and customer_user_id=uid and payment_status='paid' and order_status='completed' and coalesce(completed_at,updated_at) between start_time and finish_time;
  elsif cond.condition_type='total_spend' then select coalesce(sum(total_pence+customer_credit_used_pence+gift_card_used_pence+reward_discount_pence+vip_discount_pence+vip_delivery_discount_pence+vip_menu_item_discount_pence),0) into v from public.orders where restaurant_id=c.restaurant_id and customer_user_id=uid and payment_status='paid' and order_status='completed' and coalesce(completed_at,updated_at) between start_time and finish_time;
  elsif cond.condition_type='single_order_spend' then select coalesce(max(total_pence+customer_credit_used_pence+gift_card_used_pence+reward_discount_pence+vip_discount_pence+vip_delivery_discount_pence+vip_menu_item_discount_pence),0) into v from public.orders where restaurant_id=c.restaurant_id and customer_user_id=uid and payment_status='paid' and order_status='completed' and coalesce(completed_at,updated_at) between start_time and finish_time;
  elsif cond.condition_type in ('breakfast_orders','lunch_orders','dinner_orders') then select count(*) into v from public.orders o where o.restaurant_id=c.restaurant_id and o.customer_user_id=uid and o.payment_status='paid' and o.order_status='completed' and coalesce(o.completed_at,o.updated_at) between start_time and finish_time and case cond.condition_type when 'breakfast_orders' then extract(hour from o.created_at at time zone 'Europe/London') between 5 and 10 when 'lunch_orders' then extract(hour from o.created_at at time zone 'Europe/London') between 11 and 15 else extract(hour from o.created_at at time zone 'Europe/London') between 16 and 23 end;
  elsif cond.condition_type='weekend_orders' then select count(*) into v from public.orders o where o.restaurant_id=c.restaurant_id and o.customer_user_id=uid and o.payment_status='paid' and o.order_status='completed' and coalesce(o.completed_at,o.updated_at) between start_time and finish_time and extract(isodow from o.created_at at time zone 'Europe/London') in (6,7);
  elsif cond.condition_type='weekday_orders' then select count(*) into v from public.orders o where o.restaurant_id=c.restaurant_id and o.customer_user_id=uid and o.payment_status='paid' and o.order_status='completed' and coalesce(o.completed_at,o.updated_at) between start_time and finish_time and extract(isodow from o.created_at at time zone 'Europe/London') between 1 and 5;
  elsif cond.condition_type='distinct_menu_items' then select count(distinct oi.menu_item_id) into v from public.order_items oi join public.orders o on o.id=oi.order_id where o.restaurant_id=c.restaurant_id and o.customer_user_id=uid and o.payment_status='paid' and o.order_status='completed' and oi.menu_item_id is not null and coalesce(o.completed_at,o.updated_at) between start_time and finish_time;
  elsif cond.condition_type='distinct_categories' then select count(distinct mi.category_id) into v from public.order_items oi join public.menu_items mi on mi.id=oi.menu_item_id join public.orders o on o.id=oi.order_id where o.restaurant_id=c.restaurant_id and o.customer_user_id=uid and o.payment_status='paid' and o.order_status='completed' and coalesce(o.completed_at,o.updated_at) between start_time and finish_time;
  elsif cond.condition_type='featured_item' then select coalesce(sum(oi.quantity),0) into v from public.order_items oi join public.orders o on o.id=oi.order_id where o.restaurant_id=c.restaurant_id and o.customer_user_id=uid and o.payment_status='paid' and o.order_status='completed' and oi.menu_item_id=cond.menu_item_id and coalesce(o.completed_at,o.updated_at) between start_time and finish_time;
  elsif cond.condition_type='vip_only' then select case when exists(select 1 from public.customer_vip_memberships m where m.restaurant_id=c.restaurant_id and m.customer_user_id=uid and m.current_tier_id is not null) then cond.target_value else 0 end into v;
  elsif cond.condition_type='referral_count' then select count(*) into v from public.customer_referrals r where r.restaurant_id=c.restaurant_id and r.referrer_user_id=uid and r.status='qualified' and r.qualified_at between start_time and finish_time;
  elsif cond.condition_type='stamp_count' then select coalesce(sum(e.stamps_delta) filter(where e.stamps_delta>0),0) into v from public.customer_stamp_events e where e.restaurant_id=c.restaurant_id and e.customer_user_id=uid and e.created_at between start_time and finish_time;
  elsif cond.condition_type='points_balance' then select coalesce(points_balance,0) into v from public.customer_loyalty_accounts where restaurant_id=c.restaurant_id and customer_user_id=uid;
  elsif cond.condition_type='points_earned' then select coalesce(sum(points_delta) filter(where points_delta>0),0) into v from public.customer_loyalty_ledger where restaurant_id=c.restaurant_id and customer_user_id=uid and created_at between start_time and finish_time;
  elsif cond.condition_type='consecutive_weeks' then select coalesce(max(run),0) into v from (select count(*) over(partition by grp) run from (select week_start, week_start-(row_number() over(order by week_start)::int*7)*interval '1 day' grp from (select distinct date_trunc('week',coalesce(completed_at,updated_at))::date week_start from public.orders where restaurant_id=c.restaurant_id and customer_user_id=uid and payment_status='paid' and order_status='completed' and coalesce(completed_at,updated_at) between start_time and finish_time) w) x) y;
  elsif cond.condition_type='consecutive_months' then select coalesce(max(run),0) into v from (select count(*) over(partition by grp) run from (select month_start, month_start-(row_number() over(order by month_start)::int*interval '1 month') grp from (select distinct date_trunc('month',coalesce(completed_at,updated_at)) month_start from public.orders where restaurant_id=c.restaurant_id and customer_user_id=uid and payment_status='paid' and order_status='completed' and coalesce(completed_at,updated_at) between start_time and finish_time) m) x) y;
  elsif cond.condition_type in ('seasonal','holiday') then v:=case when now() between coalesce(nullif(cond.config->>'window_start','')::timestamptz,c.starts_at) and coalesce(nullif(cond.config->>'window_end','')::timestamptz,c.ends_at,'infinity'::timestamptz) then cond.target_value else 0 end;
  elsif cond.condition_type='custom' then key:=coalesce(cond.config->>'metric_key',''); select coalesce(metric_value,0) into v from public.customer_challenge_custom_metrics where restaurant_id=c.restaurant_id and customer_user_id=uid and metric_key=key;
  end if;
  return coalesce(v,0);
end $$;

create or replace function private.queue_challenge_notification(p_challenge_id uuid,p_progress_id uuid,p_achievement_id uuid,p_restaurant_id uuid,p_customer_user_id uuid,p_event_type text,p_subject text,p_body text,p_dedupe text)
returns void language plpgsql security definer set search_path='' as $$
begin
  insert into public.customer_notifications(customer_user_id,restaurant_id,notification_type,title,body,action_url,metadata,dedupe_key) values(p_customer_user_id,p_restaurant_id,p_event_type,p_subject,p_body,'/account/challenges',jsonb_build_object('challenge_id',p_challenge_id,'progress_id',p_progress_id,'achievement_id',p_achievement_id),p_dedupe) on conflict do nothing;
  insert into public.challenge_notification_queue(challenge_id,progress_id,achievement_id,restaurant_id,customer_user_id,event_type,subject,body,action_url,push_payload,dedupe_key) values(p_challenge_id,p_progress_id,p_achievement_id,p_restaurant_id,p_customer_user_id,p_event_type,p_subject,p_body,'/account/challenges',jsonb_build_object('type',p_event_type,'challenge_id',p_challenge_id,'achievement_id',p_achievement_id,'action_url','/account/challenges'),p_dedupe) on conflict(dedupe_key) do nothing;
end $$;

create or replace function private.issue_challenge_reward(p_progress_id uuid,p_reward_id uuid,p_order_id uuid)
returns uuid language plpgsql security definer set search_path='' as $$
declare cp public.customer_challenge_progress%rowtype; rw public.restaurant_challenge_rewards%rowtype; c public.restaurant_challenges%rowtype; iid uuid; mapped text; source_key text; ledger uuid; acct public.customer_loyalty_accounts%rowtype; vip_key text;
begin
  select * into cp from public.customer_challenge_progress where id=p_progress_id; select * into rw from public.restaurant_challenge_rewards where id=p_reward_id and challenge_id=cp.challenge_id; select * into c from public.restaurant_challenges where id=cp.challenge_id;
  if cp.id is null or rw.id is null then return null; end if;
  source_key:=cp.cycle_key||':'||rw.id::text;
  mapped:=case rw.reward_type when 'fixed_voucher' then 'fixed_discount' when 'percentage_voucher' then 'percentage_discount' when 'store_credit' then 'wallet_credit' else rw.reward_type end;
  insert into public.customer_reward_issuances(restaurant_id,customer_user_id,source_type,source_id,source_key,triggering_order_id,reward_type,reward_value,reward_catalogue_id,status,eligible_at,expires_at,metadata)
  values(cp.restaurant_id,cp.customer_user_id,'challenge',cp.challenge_id,source_key,p_order_id,mapped,rw.reward_value,rw.reward_catalogue_id,'pending',now(),case when rw.validity_days is null then null else now()+make_interval(days=>rw.validity_days) end,jsonb_build_object('challenge_name',c.name,'challenge_progress_id',cp.id,'challenge_reward_id',rw.id,'campaign_message','Challenge complete: '||c.name)) on conflict(restaurant_id,customer_user_id,source_type,source_id,source_key) do nothing returning id into iid;
  if iid is null then select id into iid from public.customer_reward_issuances where restaurant_id=cp.restaurant_id and customer_user_id=cp.customer_user_id and source_type='challenge' and source_id=cp.challenge_id and source_key=source_key; return iid; end if;
  if rw.reward_type='bonus_stamps' then perform public.add_customer_stamp_progress(rw.stamp_program_id,cp.customer_user_id,greatest(rw.reward_value,1),'challenge_bonus','Challenge reward: '||c.name,null); update public.customer_reward_issuances set status='available',issued_at=now(),campaign_cost_pence=0,updated_at=now() where id=iid;
  elsif rw.reward_type='vip_bonus' then vip_key:=coalesce(nullif(rw.config->>'metric_key',''),'challenge_bonus'); insert into public.customer_vip_custom_metrics(restaurant_id,customer_user_id,metric_key,metric_value,updated_by) values(cp.restaurant_id,cp.customer_user_id,vip_key,greatest(rw.reward_value,1),null) on conflict(restaurant_id,customer_user_id,metric_key) do update set metric_value=public.customer_vip_custom_metrics.metric_value+excluded.metric_value,updated_at=now(); perform private.evaluate_customer_vip_tier(cp.restaurant_id,cp.customer_user_id,'challenge_reward','system',null); update public.customer_reward_issuances set status='available',issued_at=now(),updated_at=now() where id=iid;
  elsif rw.reward_type='referral_bonus' then insert into public.customer_loyalty_accounts(restaurant_id,customer_user_id,points_balance,lifetime_points_earned,lifetime_points_redeemed) values(cp.restaurant_id,cp.customer_user_id,0,0,0) on conflict(restaurant_id,customer_user_id) do nothing; select * into acct from public.customer_loyalty_accounts where restaurant_id=cp.restaurant_id and customer_user_id=cp.customer_user_id for update; insert into public.customer_loyalty_ledger(loyalty_account_id,restaurant_id,customer_user_id,points_delta,entry_type,note,reward_issuance_id) values(acct.id,cp.restaurant_id,cp.customer_user_id,greatest(rw.reward_value,1),'challenge_bonus','Referral challenge bonus',iid) on conflict(reward_issuance_id) where reward_issuance_id is not null do nothing returning id into ledger; if ledger is not null then update public.customer_loyalty_accounts set points_balance=points_balance+greatest(rw.reward_value,1),lifetime_points_earned=lifetime_points_earned+greatest(rw.reward_value,1),updated_at=now() where id=acct.id; end if; update public.customer_reward_issuances set status='available',issued_at=now(),loyalty_ledger_id=ledger,updated_at=now() where id=iid;
  else perform private.issue_campaign_reward(iid); end if;
  return iid;
end $$;

create or replace function private.evaluate_customer_challenge(p_challenge_id uuid,p_customer_user_id uuid,p_event_key text,p_order_id uuid default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare c public.restaurant_challenges%rowtype; cycle text; cp public.customer_challenge_progress%rowtype; cond record; reward record; vals jsonb:='{}'::jsonb; met integer:=0; total integer:=0; pct numeric:=0; val bigint; completed boolean:=false; previous numeric:=0; result jsonb;
begin
 select * into c from public.restaurant_challenges where id=p_challenge_id and is_active and platform_disabled_at is null;
 if not found or now()<c.starts_at or (c.ends_at is not null and now()>c.ends_at) or not private.challenge_audience_matches(c,p_customer_user_id) then return jsonb_build_object('eligible',false); end if;
 cycle:=private.challenge_cycle_key(c,now());
 insert into public.customer_challenge_progress(challenge_id,restaurant_id,customer_user_id,cycle_key) values(c.id,c.restaurant_id,p_customer_user_id,cycle) on conflict(challenge_id,customer_user_id,cycle_key) do nothing;
 select * into cp from public.customer_challenge_progress where challenge_id=c.id and customer_user_id=p_customer_user_id and cycle_key=cycle for update; previous:=cp.progress_percent;
 if exists(select 1 from public.challenge_progress_events where progress_id=cp.id and event_key=p_event_key) then return jsonb_build_object('eligible',true,'progress_id',cp.id,'progress_percent',cp.progress_percent,'status',cp.status,'idempotent',true); end if;
 if cp.status='completed' then return jsonb_build_object('eligible',true,'progress_id',cp.id,'progress_percent',100,'status','completed'); end if;
 for cond in select * from public.restaurant_challenge_conditions where challenge_id=c.id order by sort_order,created_at loop total:=total+1; val:=private.challenge_metric_value(cond,c,p_customer_user_id,p_order_id); vals:=vals||jsonb_build_object(cond.id::text,jsonb_build_object('type',cond.condition_type,'value',val,'target',cond.target_value,'percent',least(100,round(100.0*val/cond.target_value,2)))); if val>=cond.target_value then met:=met+1; end if; pct:=pct+least(100,100.0*val/cond.target_value); end loop;
 if total=0 then return jsonb_build_object('eligible',false,'reason','no_conditions'); end if; if c.condition_match='any' then completed:=met>0; pct:=case when completed then 100 else pct/total end; else completed:=met=total; pct:=pct/total; end if; pct:=least(100,round(pct,2));
 update public.customer_challenge_progress set progress_percent=pct,progress=vals,last_progress_at=now(),estimated_completion_at=case when pct>0 and pct<100 and c.ends_at is not null then least(c.ends_at,now()+((c.ends_at-c.starts_at)*(100-pct)/greatest(pct,1))) else estimated_completion_at end,status=case when completed then 'completed' else status end,completed_at=case when completed then coalesce(completed_at,now()) else completed_at end,completion_order_id=case when completed then coalesce(completion_order_id,p_order_id) else completion_order_id end,completion_number=case when completed then completion_number+1 else completion_number end,updated_at=now() where id=cp.id returning * into cp;
 insert into public.challenge_progress_events(progress_id,challenge_id,restaurant_id,customer_user_id,order_id,event_key,event_type,previous_percent,new_percent,details) values(cp.id,c.id,c.restaurant_id,p_customer_user_id,p_order_id,p_event_key,case when completed then 'completed' else 'progress' end,previous,pct,jsonb_build_object('conditions',vals)) on conflict(progress_id,event_key) do nothing;
 if previous<80 and pct>=80 and not completed then perform private.queue_challenge_notification(c.id,cp.id,null,c.restaurant_id,p_customer_user_id,'challenge_nearly_complete','Almost there',c.name||' is nearly complete.','challenge-near:'||cp.id::text||':'||cycle); end if;
 if completed then for reward in select * from public.restaurant_challenge_rewards where challenge_id=c.id order by sort_order loop perform private.issue_challenge_reward(cp.id,reward.id,p_order_id); end loop; perform private.queue_challenge_notification(c.id,cp.id,null,c.restaurant_id,p_customer_user_id,'challenge_completed','Challenge completed','You completed '||c.name||'. Your rewards are ready.','challenge-complete:'||cp.id::text); end if;
 return jsonb_build_object('eligible',true,'progress_id',cp.id,'progress_percent',pct,'status',cp.status,'completed',completed,'conditions',vals);
end $$;

create or replace function private.evaluate_customer_achievements(p_restaurant_id uuid,p_customer_user_id uuid,p_order_id uuid default null)
returns integer language plpgsql security definer set search_path='' as $$
declare a record; val bigint; unlocked integer:=0;
begin
 for a in select * from public.restaurant_achievements where is_active and (restaurant_id is null or restaurant_id=p_restaurant_id) loop
  val:=case a.achievement_type when 'orders' then (select count(*) from public.orders where restaurant_id=p_restaurant_id and customer_user_id=p_customer_user_id and payment_status='paid' and order_status='completed') when 'weekend_orders' then (select count(*) from public.orders where restaurant_id=p_restaurant_id and customer_user_id=p_customer_user_id and payment_status='paid' and order_status='completed' and extract(isodow from created_at at time zone 'Europe/London') in(6,7)) when 'breakfast_orders' then (select count(*) from public.orders where restaurant_id=p_restaurant_id and customer_user_id=p_customer_user_id and payment_status='paid' and order_status='completed' and extract(hour from created_at at time zone 'Europe/London') between 5 and 10) when 'lunch_orders' then (select count(*) from public.orders where restaurant_id=p_restaurant_id and customer_user_id=p_customer_user_id and payment_status='paid' and order_status='completed' and extract(hour from created_at at time zone 'Europe/London') between 11 and 15) when 'dinner_orders' then (select count(*) from public.orders where restaurant_id=p_restaurant_id and customer_user_id=p_customer_user_id and payment_status='paid' and order_status='completed' and extract(hour from created_at at time zone 'Europe/London') between 16 and 23) when 'distinct_items' then (select count(distinct oi.menu_item_id) from public.order_items oi join public.orders o on o.id=oi.order_id where o.restaurant_id=p_restaurant_id and o.customer_user_id=p_customer_user_id and o.payment_status='paid' and o.order_status='completed' and oi.menu_item_id is not null) when 'vip_member' then case when exists(select 1 from public.customer_vip_memberships where restaurant_id=p_restaurant_id and customer_user_id=p_customer_user_id and current_tier_id is not null) then 1 else 0 end when 'referrals' then (select count(*) from public.customer_referrals where restaurant_id=p_restaurant_id and referrer_user_id=p_customer_user_id and status='qualified') when 'stamps' then coalesce((select sum(stamps_delta) filter(where stamps_delta>0) from public.customer_stamp_events where restaurant_id=p_restaurant_id and customer_user_id=p_customer_user_id),0) when 'spend' then coalesce((select sum(total_pence+customer_credit_used_pence+gift_card_used_pence+reward_discount_pence) from public.orders where restaurant_id=p_restaurant_id and customer_user_id=p_customer_user_id and payment_status='paid' and order_status='completed'),0) when 'custom' then coalesce((select metric_value from public.customer_challenge_custom_metrics where restaurant_id=p_restaurant_id and customer_user_id=p_customer_user_id and metric_key=coalesce(a.config->>'metric_key','')),0) else 0 end;
  if val>=a.target_value then insert into public.customer_achievement_unlocks(achievement_id,restaurant_id,customer_user_id,source_order_id,progress_value,metadata) values(a.id,p_restaurant_id,p_customer_user_id,p_order_id,val,jsonb_build_object('achievement_key',a.achievement_key)) on conflict(achievement_id,restaurant_id,customer_user_id) do nothing; if found then unlocked:=unlocked+1; perform private.queue_challenge_notification(null,null,a.id,p_restaurant_id,p_customer_user_id,'achievement_unlocked','Achievement unlocked',a.name||': '||a.description,'achievement:'||a.id::text||':'||p_restaurant_id::text||':'||p_customer_user_id::text); end if; end if;
 end loop; return unlocked;
end $$;

create or replace function private.process_completed_order_challenges() returns trigger language plpgsql security definer set search_path='' as $$
declare c record; recent_count integer;
begin
 if new.order_status='completed' and new.payment_status='paid' and new.customer_user_id is not null and (old.order_status is distinct from new.order_status or old.payment_status is distinct from new.payment_status) then
   select count(*) into recent_count from public.orders o where o.restaurant_id=new.restaurant_id and o.customer_user_id=new.customer_user_id and o.id<>new.id and o.payment_status='paid' and o.order_status='completed' and o.total_pence=new.total_pence and coalesce(o.completed_at,o.updated_at)>coalesce(new.completed_at,new.updated_at)-interval '2 minutes';
   if recent_count>0 then insert into public.challenge_fraud_flags(restaurant_id,customer_user_id,order_id,flag_type,severity,details) values(new.restaurant_id,new.customer_user_id,new.id,'rapid_duplicate_order','medium',jsonb_build_object('matching_recent_orders',recent_count,'total_pence',new.total_pence)); end if;
   for c in select id from public.restaurant_challenges where restaurant_id=new.restaurant_id and is_active and platform_disabled_at is null and starts_at<=coalesce(new.completed_at,now()) and (ends_at is null or ends_at>=coalesce(new.completed_at,now())) order by priority desc loop perform private.evaluate_customer_challenge(c.id,new.customer_user_id,'order:'||new.id::text,new.id); end loop;
   perform private.evaluate_customer_achievements(new.restaurant_id,new.customer_user_id,new.id);
 end if; return new;
end $$;
drop trigger if exists orders_challenge_completion_trigger on public.orders;
create trigger orders_challenge_completion_trigger after update of order_status,payment_status on public.orders for each row execute function private.process_completed_order_challenges();

create or replace function public.record_challenge_custom_metric(p_metric_key text,p_metric_value bigint,p_source_key text,p_customer_user_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare rid uuid:=private.challenge_restaurant_id(true); c record; old_value bigint:=0;
begin
 if lower(trim(p_metric_key)) !~ '^[a-z0-9_]{1,64}$' or p_metric_value<0 or nullif(trim(p_source_key),'') is null then raise exception 'Invalid custom metric'; end if;
 select metric_value into old_value from public.customer_challenge_custom_metrics where restaurant_id=rid and customer_user_id=p_customer_user_id and metric_key=lower(trim(p_metric_key)); old_value:=coalesce(old_value,0);
 insert into public.customer_challenge_custom_metrics(restaurant_id,customer_user_id,metric_key,metric_value,source_key) values(rid,p_customer_user_id,lower(trim(p_metric_key)),p_metric_value,trim(p_source_key)) on conflict(restaurant_id,customer_user_id,metric_key) do update set metric_value=excluded.metric_value,source_key=excluded.source_key,updated_at=now();
 if old_value>0 and p_metric_value>old_value*10 then insert into public.challenge_fraud_flags(restaurant_id,customer_user_id,flag_type,severity,details) values(rid,p_customer_user_id,'large_manual_metric_change','medium',jsonb_build_object('metric_key',p_metric_key,'previous_value',old_value,'new_value',p_metric_value,'actor',auth.uid())); end if;
 for c in select id from public.restaurant_challenges where restaurant_id=rid and is_active and platform_disabled_at is null loop perform private.evaluate_customer_challenge(c.id,p_customer_user_id,'custom:'||trim(p_source_key),null); end loop; perform private.evaluate_customer_achievements(rid,p_customer_user_id,null); return jsonb_build_object('metric_key',lower(trim(p_metric_key)),'metric_value',p_metric_value);
end $$;

create or replace function public.get_customer_challenges() returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid(); c record; pref jsonb;
begin if uid is null then raise exception 'Authentication required' using errcode='42501'; end if; for c in select id from public.restaurant_challenges ch where ch.is_active and ch.platform_disabled_at is null and ch.starts_at<=now() and (ch.ends_at is null or ch.ends_at>now()) and (exists(select 1 from public.orders o where o.restaurant_id=ch.restaurant_id and o.customer_user_id=uid) or exists(select 1 from public.customer_loyalty_accounts l where l.restaurant_id=ch.restaurant_id and l.customer_user_id=uid)) loop perform private.evaluate_customer_challenge(c.id,uid,'dashboard:'||to_char(now(),'YYYYMMDDHH24'),null); end loop; return jsonb_build_object('active',coalesce((select jsonb_agg(jsonb_build_object('challenge_id',ch.id,'restaurant_id',ch.restaurant_id,'restaurant_name',r.name,'restaurant_slug',r.slug,'name',ch.name,'description',ch.description,'icon',ch.icon,'colour',ch.colour,'banner_image_url',ch.banner_image_url,'starts_at',ch.starts_at,'ends_at',ch.ends_at,'priority',ch.priority,'progress_id',cp.id,'progress_percent',coalesce(cp.progress_percent,0),'progress',coalesce(cp.progress,'{}'::jsonb),'estimated_completion_at',cp.estimated_completion_at,'rewards',coalesce((select jsonb_agg(to_jsonb(cr)-'restaurant_id'-'challenge_id') from public.restaurant_challenge_rewards cr where cr.challenge_id=ch.id),'[]'::jsonb)) order by ch.priority desc,ch.ends_at nulls last) from public.restaurant_challenges ch join public.restaurants r on r.id=ch.restaurant_id left join public.customer_challenge_progress cp on cp.challenge_id=ch.id and cp.customer_user_id=uid and cp.cycle_key=private.challenge_cycle_key(ch,now()) where ch.is_active and ch.platform_disabled_at is null and ch.visibility<>'hidden' and ch.starts_at<=now() and (ch.ends_at is null or ch.ends_at>now()) and private.challenge_audience_matches(ch,uid) and coalesce(cp.status,'active')='active'),'[]'::jsonb),'upcoming',coalesce((select jsonb_agg(jsonb_build_object('challenge_id',ch.id,'restaurant_name',r.name,'name',ch.name,'description',ch.description,'icon',ch.icon,'colour',ch.colour,'starts_at',ch.starts_at,'ends_at',ch.ends_at) order by ch.starts_at) from public.restaurant_challenges ch join public.restaurants r on r.id=ch.restaurant_id where ch.is_active and ch.platform_disabled_at is null and ch.visibility<>'hidden' and ch.starts_at>now() and private.challenge_audience_matches(ch,uid)),'[]'::jsonb),'completed',coalesce((select jsonb_agg(jsonb_build_object('progress_id',cp.id,'challenge_id',ch.id,'restaurant_name',r.name,'name',ch.name,'icon',ch.icon,'colour',ch.colour,'completed_at',cp.completed_at,'cycle_key',cp.cycle_key,'rewards',coalesce((select jsonb_agg(jsonb_build_object('status',i.status,'reward_type',i.reward_type,'reward_value',i.reward_value,'issued_at',i.issued_at,'expires_at',i.expires_at)) from public.customer_reward_issuances i where i.source_type='challenge' and i.source_id=ch.id and i.customer_user_id=uid and i.metadata->>'challenge_progress_id'=cp.id::text),'[]'::jsonb)) order by cp.completed_at desc) from public.customer_challenge_progress cp join public.restaurant_challenges ch on ch.id=cp.challenge_id join public.restaurants r on r.id=cp.restaurant_id where cp.customer_user_id=uid and cp.status='completed'),'[]'::jsonb),'achievements',coalesce((select jsonb_agg(jsonb_build_object('id',u.id,'achievement_id',a.id,'restaurant_id',u.restaurant_id,'name',a.name,'description',a.description,'icon',a.icon,'colour',a.colour,'unlocked_at',u.unlocked_at) order by u.unlocked_at desc) from public.customer_achievement_unlocks u join public.restaurant_achievements a on a.id=u.achievement_id where u.customer_user_id=uid),'[]'::jsonb),'preferences',coalesce((select jsonb_agg(to_jsonb(g)-'customer_user_id') from public.customer_gamification_preferences g where g.customer_user_id=uid),'[]'::jsonb)); end $$;

create or replace function public.get_restaurant_challenge_dashboard() returns jsonb language plpgsql security definer set search_path='' as $$
declare rid uuid:=private.challenge_restaurant_id(false);
begin return jsonb_build_object('summary',jsonb_build_object('active_challenges',(select count(*) from public.restaurant_challenges where restaurant_id=rid and is_active and platform_disabled_at is null and starts_at<=now() and (ends_at is null or ends_at>now())),'participants',(select count(distinct customer_user_id) from public.customer_challenge_progress where restaurant_id=rid),'completions',(select count(*) from public.customer_challenge_progress where restaurant_id=rid and status='completed'),'completion_percent',case when (select count(*) from public.customer_challenge_progress where restaurant_id=rid)=0 then 0 else round(100.0*(select count(*) from public.customer_challenge_progress where restaurant_id=rid and status='completed')/(select count(*) from public.customer_challenge_progress where restaurant_id=rid),1) end,'revenue_generated_pence',coalesce((select sum(revenue_generated_pence) from public.customer_reward_issuances where restaurant_id=rid and source_type='challenge'),0),'reward_cost_pence',coalesce((select sum(campaign_cost_pence) from public.customer_reward_issuances where restaurant_id=rid and source_type='challenge'),0),'average_spend_pence',coalesce((select round(avg(total_pence)) from public.orders where restaurant_id=rid and customer_user_id in(select customer_user_id from public.customer_challenge_progress where restaurant_id=rid) and payment_status='paid' and order_status='completed'),0),'repeat_visits',(select count(*) from public.customer_reward_issuances where restaurant_id=rid and source_type='challenge' and converted_order_id is not null)),'challenges',coalesce((select jsonb_agg(to_jsonb(c)||jsonb_build_object('conditions',(select coalesce(jsonb_agg(to_jsonb(cc)-'restaurant_id'-'challenge_id' order by sort_order),'[]'::jsonb) from public.restaurant_challenge_conditions cc where cc.challenge_id=c.id),'rewards',(select coalesce(jsonb_agg(to_jsonb(cr)-'restaurant_id'-'challenge_id' order by sort_order),'[]'::jsonb) from public.restaurant_challenge_rewards cr where cr.challenge_id=c.id),'participants',(select count(distinct customer_user_id) from public.customer_challenge_progress p where p.challenge_id=c.id),'completions',(select count(*) from public.customer_challenge_progress p where p.challenge_id=c.id and p.status='completed'),'revenue_generated_pence',coalesce((select sum(revenue_generated_pence) from public.customer_reward_issuances i where i.source_type='challenge' and i.source_id=c.id),0),'reward_cost_pence',coalesce((select sum(campaign_cost_pence) from public.customer_reward_issuances i where i.source_type='challenge' and i.source_id=c.id),0)) order by c.priority desc,c.created_at desc) from public.restaurant_challenges c where c.restaurant_id=rid),'[]'::jsonb),'achievements',coalesce((select jsonb_agg(to_jsonb(a)-'created_by' order by is_system_default desc,name) from public.restaurant_achievements a where a.is_active and (a.restaurant_id is null or a.restaurant_id=rid)),'[]'::jsonb),'leaderboard_settings',coalesce((select to_jsonb(s)-'updated_by' from public.restaurant_leaderboard_settings s where s.restaurant_id=rid),jsonb_build_object('is_enabled',false,'metric','points','max_entries',25)),'fraud_flags',coalesce((select jsonb_agg(to_jsonb(f) order by created_at desc) from (select * from public.challenge_fraud_flags where restaurant_id=rid order by created_at desc limit 100)f),'[]'::jsonb)); end $$;

create or replace function public.get_restaurant_challenge_leaderboard() returns jsonb language plpgsql security definer set search_path='' as $$
declare rid uuid:=private.challenge_restaurant_id(false); settings public.restaurant_leaderboard_settings%rowtype;
begin select * into settings from public.restaurant_leaderboard_settings where restaurant_id=rid; if not found or not settings.is_enabled then return '[]'::jsonb; end if; return coalesce((select jsonb_agg(row_data order by score desc) from (select jsonb_build_object('customer_user_id',x.customer_user_id,'display_name',case coalesce(pref.leaderboard_visibility,'anonymous') when 'nickname' then coalesce(pref.nickname,'Player') else 'Anonymous' end,'score',x.score) row_data,x.score from (select u.customer_user_id,case settings.metric when 'points' then coalesce((select a.points_balance from public.customer_loyalty_accounts a where a.restaurant_id=rid and a.customer_user_id=u.customer_user_id),0) when 'challenges' then (select count(*) from public.customer_challenge_progress p where p.restaurant_id=rid and p.customer_user_id=u.customer_user_id and p.status='completed') when 'referrals' then (select count(*) from public.customer_referrals r where r.restaurant_id=rid and r.referrer_user_id=u.customer_user_id and r.status='qualified') when 'stamps' then coalesce((select sum(e.stamps_delta) filter(where e.stamps_delta>0) from public.customer_stamp_events e where e.restaurant_id=rid and e.customer_user_id=u.customer_user_id),0) else (select count(*) from public.orders o where o.restaurant_id=rid and o.customer_user_id=u.customer_user_id and o.payment_status='paid' and o.order_status='completed') end::bigint score from (select distinct customer_user_id from public.orders where restaurant_id=rid and customer_user_id is not null union select distinct customer_user_id from public.customer_challenge_progress where restaurant_id=rid)u)x left join public.customer_gamification_preferences pref on pref.restaurant_id=rid and pref.customer_user_id=x.customer_user_id where coalesce(pref.leaderboard_visibility,'anonymous')<>'hidden' order by x.score desc limit settings.max_entries)s),'[]'::jsonb); end $$;

create or replace function public.get_platform_challenge_dashboard() returns jsonb language plpgsql security definer set search_path='' as $$
begin if not private.has_platform_admin_permission('overview:view') then raise exception 'Platform overview permission required' using errcode='42501'; end if; return jsonb_build_object('summary',jsonb_build_object('restaurant_adoption',(select count(distinct restaurant_id) from public.restaurant_challenges),'active_restaurants',(select count(distinct restaurant_id) from public.restaurant_challenges where is_active and platform_disabled_at is null and starts_at<=now() and (ends_at is null or ends_at>now())),'participants',(select count(distinct customer_user_id) from public.customer_challenge_progress),'completions',(select count(*) from public.customer_challenge_progress where status='completed'),'completion_percent',case when (select count(*) from public.customer_challenge_progress)=0 then 0 else round(100.0*(select count(*) from public.customer_challenge_progress where status='completed')/(select count(*) from public.customer_challenge_progress),1) end,'reward_cost_pence',coalesce((select sum(campaign_cost_pence) from public.customer_reward_issuances where source_type='challenge'),0),'revenue_generated_pence',coalesce((select sum(revenue_generated_pence) from public.customer_reward_issuances where source_type='challenge'),0),'open_fraud_flags',(select count(*) from public.challenge_fraud_flags where status='open')),'challenge_types',coalesce((select jsonb_agg(jsonb_build_object('condition_type',condition_type,'challenges',challenge_count,'completions',completions) order by completions desc,challenge_count desc) from (select cc.condition_type,count(distinct cc.challenge_id) challenge_count,count(distinct p.id) filter(where p.status='completed') completions from public.restaurant_challenge_conditions cc left join public.customer_challenge_progress p on p.challenge_id=cc.challenge_id group by cc.condition_type)t),'[]'::jsonb),'restaurants',coalesce((select jsonb_agg(jsonb_build_object('restaurant_id',r.id,'restaurant_name',r.name,'challenges',(select count(*) from public.restaurant_challenges c where c.restaurant_id=r.id),'participants',(select count(distinct customer_user_id) from public.customer_challenge_progress p where p.restaurant_id=r.id),'completions',(select count(*) from public.customer_challenge_progress p where p.restaurant_id=r.id and p.status='completed'),'reward_cost_pence',coalesce((select sum(campaign_cost_pence) from public.customer_reward_issuances i where i.restaurant_id=r.id and i.source_type='challenge'),0),'revenue_generated_pence',coalesce((select sum(revenue_generated_pence) from public.customer_reward_issuances i where i.restaurant_id=r.id and i.source_type='challenge'),0)) order by r.name) from public.restaurants r where exists(select 1 from public.restaurant_challenges c where c.restaurant_id=r.id)),'[]'::jsonb),'fraud_flags',coalesce((select jsonb_agg(to_jsonb(f)||jsonb_build_object('restaurant_name',r.name) order by f.created_at desc) from (select * from public.challenge_fraud_flags order by created_at desc limit 200)f join public.restaurants r on r.id=f.restaurant_id),'[]'::jsonb)); end $$;
create or replace function public.platform_set_challenge_disabled(p_challenge_id uuid,p_disabled boolean,p_reason text) returns void language plpgsql security definer set search_path='' as $$ begin if not private.has_platform_admin_permission('overview:view') then raise exception 'Platform overview permission required' using errcode='42501'; end if; update public.restaurant_challenges set platform_disabled_at=case when p_disabled then now() else null end,platform_disabled_reason=case when p_disabled then nullif(trim(p_reason),'') else null end,updated_at=now() where id=p_challenge_id; end $$;
create or replace function public.platform_review_challenge_fraud_flag(p_flag_id uuid,p_status text,p_note text) returns void language plpgsql security definer set search_path='' as $$ begin if not private.has_platform_admin_permission('overview:view') then raise exception 'Platform overview permission required' using errcode='42501'; end if; update public.challenge_fraud_flags set status=p_status,review_note=nullif(trim(p_note),''),reviewed_by=auth.uid(),reviewed_at=now() where id=p_flag_id; end $$;
create or replace function public.process_challenge_notifications(p_now timestamptz default now()) returns jsonb language plpgsql security definer set search_path='' as $$ declare c record; p record; queued integer:=0; begin if current_user not in ('postgres','service_role') and coalesce(auth.jwt()->>'role','')<>'service_role' then raise exception 'Service role required' using errcode='42501'; end if; for c in select * from public.restaurant_challenges where is_active and platform_disabled_at is null and starts_at between p_now and p_now+interval '24 hours' loop for p in select distinct customer_user_id from public.orders where restaurant_id=c.restaurant_id and customer_user_id is not null loop if private.challenge_audience_matches(c,p.customer_user_id) then perform private.queue_challenge_notification(c.id,null,null,c.restaurant_id,p.customer_user_id,'challenge_starting','Challenge starting soon',c.name||' starts soon.','challenge-starting:'||c.id::text||':'||p.customer_user_id::text); queued:=queued+1; end if; end loop; end loop; for p in select cp.*,c.name,c.ends_at from public.customer_challenge_progress cp join public.restaurant_challenges c on c.id=cp.challenge_id where cp.status='active' and c.ends_at between p_now and p_now+interval '48 hours' loop perform private.queue_challenge_notification(p.challenge_id,p.id,null,p.restaurant_id,p.customer_user_id,'challenge_expiring','Challenge ending soon',p.name||' ends soon.','challenge-expiring:'||p.id::text); queued:=queued+1; end loop; return jsonb_build_object('queued',queued); end $$;
revoke all on function public.record_challenge_custom_metric(text,bigint,text,uuid) from public; grant execute on function public.record_challenge_custom_metric(text,bigint,text,uuid) to authenticated;
revoke all on function public.get_customer_challenges() from public; grant execute on function public.get_customer_challenges() to authenticated;
revoke all on function public.get_restaurant_challenge_dashboard() from public; grant execute on function public.get_restaurant_challenge_dashboard() to authenticated;
revoke all on function public.get_restaurant_challenge_leaderboard() from public; grant execute on function public.get_restaurant_challenge_leaderboard() to authenticated;
revoke all on function public.get_platform_challenge_dashboard() from public; grant execute on function public.get_platform_challenge_dashboard() to authenticated;
revoke all on function public.platform_set_challenge_disabled(uuid,boolean,text) from public; grant execute on function public.platform_set_challenge_disabled(uuid,boolean,text) to authenticated;
revoke all on function public.platform_review_challenge_fraud_flag(uuid,text,text) from public; grant execute on function public.platform_review_challenge_fraud_flag(uuid,text,text) to authenticated;
revoke all on function public.process_challenge_notifications(timestamptz) from public; grant execute on function public.process_challenge_notifications(timestamptz) to service_role;
